// components/Navbar.tsx
'use client';

import Link from 'next/link';
import { usePathname } from 'next/navigation';

export default function Navbar() {
  const pathname = usePathname();
  const isAdmin = pathname?.startsWith('/admin');

  return (
    <header className="sticky top-0 z-50 bg-white shadow-md border-b border-gray-100">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 h-16 flex items-center justify-between">
        
        {/* Logo / Brand Web Pendidikan */}
        <Link href="/" className="flex items-center gap-2">
          <div className="w-10 h-10 rounded-xl bg-indigo-600 flex items-center justify-center text-white font-bold text-xl shadow-lg shadow-indigo-200">
            E
          </div>
          <div>
            <span className="text-xl font-extrabold text-gray-800 tracking-tight">EduBelajar</span>
            <span className="text-xs block text-indigo-600 font-medium">Platform Seru Anak SMP</span>
          </div>
        </Link>

        {/* Menu Navigasi Utama */}
        <nav className="hidden md:flex items-center gap-6">
          <Link 
            href="/" 
            className={`font-medium transition-colors ${pathname === '/' ? 'text-indigo-600 font-semibold' : 'text-gray-600 hover:text-indigo-600'}`}
          >
            Beranda
          </Link>
          <Link 
            href="/materi" 
            className={`font-medium transition-colors ${pathname?.startsWith('/materi') ? 'text-indigo-600 font-semibold' : 'text-gray-600 hover:text-indigo-600'}`}
          >
            Materi Pelajaran
          </Link>
          <Link 
            href="/kuis/quizizz" 
            className={`font-medium transition-colors ${pathname?.startsWith('/kuis') ? 'text-indigo-600 font-semibold' : 'text-gray-600 hover:text-indigo-600'}`}
          >
            Kuis Interaktif
          </Link>
        </nav>

        {/* Tombol Pengalih Siswa / Guru (Admin CMS) */}
        <div className="flex items-center gap-3">
          {isAdmin ? (
            <Link 
              href="/" 
              className="text-xs sm:text-sm bg-gray-100 hover:bg-gray-200 text-gray-700 font-semibold px-4 py-2 rounded-lg transition-all"
            >
              Keluar ke Mode Siswa
            </Link>
          ) : (
            <Link 
              href="/admin/materi" 
              className="text-xs sm:text-sm bg-indigo-50 hover:bg-indigo-100 text-indigo-700 font-semibold px-4 py-2 rounded-lg transition-all border border-indigo-200"
            >
              Kanal Guru (CMS)
            </Link>
          )}
        </div>

      </div>
    </header>
  );
}